{
  "claim": "For non-headline hyperscaler list-price series whose median last changed fewer than 22 days ago, the series' own empirical change quantiles will reduce pinball loss relative to the current system.",
  "mechanism": "The hypothesis is that these published medians move through discrete provider list-price resets, with persistence and jump sizes specific to each series. Drift preserves that series' empirical horizon-specific change distribution; the supplied breakdown favors it over the current system both below 4 days since change (+0.247 versus -0.012 skill) and at 4–21 days (+0.102 versus -0.025).",
  "spec": {
    "when": {
      "all": [
        {
          "fact": "cls",
          "op": "==",
          "value": "hyperscaler_list"
        },
        {
          "fact": "days_since_change",
          "op": "<",
          "value": 22
        },
        {
          "fact": "in37",
          "op": "==",
          "value": false
        }
      ]
    },
    "do": {
      "action": "members_only",
      "members": ["drift"]
    }
  },
  "falsification": "Reject if pooled skill fails to rise overall or in either selection half, fewer than 200 cells across at least 5 series actually change, headline skill falls, or fewer than 90% of the 2000 ISO-week block bootstrap resamples show improvement.",
  "prior_ids_used": [],
  "expects": "A modest pooled skill increase from lower loss on recently changed hyperscaler list prices, with headline forecasts unchanged. The reported slices support the direction, but do not establish the gain after excluding headline series, the number of changed cells, or temporal and bootstrap stability."
}
